3	function isNeighbor([x1, y1]: Cell, [x2, y2]: Cell): boolean {
4	  return Math.abs(x1 - x2) <= 1 && Math.abs(y1 - y2) <= 1 && !(x1 === x2 && y1 === y2);
5	}
6	
7	export function nextGeneration(liveCells: Cell[]): Cell[] {
8	  return liveCells.filter(
9	    (cell) => liveCells.filter((other) => isNeighbor(cell, other)).length === 2,
10	  );
11	}
